const componentFolder = {
  meta: {
    type: 'problem',
    schema: [],
    messages: {
      folder: '{{ name }} must live in {{ name }}/{{ file }}: one folder per component or hook, holding its styles and sub-parts.',
      barrel: 'No index barrel: import the file itself ({{ dir }}/{{ dir }}).',
    },
