import { useCallback, useEffect, useState } from 'react'

import type { ExpenseViewModel, FieldErrors, NewExpense } from '../../application/ExpenseViewModel'
import { useExpenseUseCases } from '../useExpenseUseCases/useExpenseUseCases'

export const useExpenses = () => {
  const { listExpenses, submitExpense } = useExpenseUseCases()
  const [expenses, setExpenses] = useState<ExpenseViewModel[]>([])
  const [loading, setLoading] = useState(true)
  const [loadFailed, setLoadFailed] = useState(false)
  const [submitFailed, setSubmitFailed] = useState(false)
  const [errors, setErrors] = useState<FieldErrors>({})

  useEffect(() => {
    let active = true
    listExpenses
      .execute()
      .then((result) => active && setExpenses(result))
      .catch(() => active && setLoadFailed(true))
      .finally(() => active && setLoading(false))
    return () => {
      active = false
    }
  }, [listExpenses])

  const submit = useCallback(
    async (expense: NewExpense): Promise<boolean> => {
      setSubmitFailed(false)
      try {
        const result = await submitExpense.execute(expense)
        if (!result.ok) {
          setErrors(result.errors)
          return false
        }
        setErrors({})
        setExpenses((current) => [...current, result.expense])
        return true
      } catch {
        setSubmitFailed(true)
        return false
      }
    },
    [submitExpense],
  )

  return { expenses, loading, loadFailed, submitFailed, errors, submit }
}
